function mergeExecutionFields(target,status){return{...target,executionPaused:status.executionPaused,cycleActive:status.cycleActive,executionBusy:status.executionBusy,recoveryRequired:status.recoveryRequired,staleExecution:status.staleExecution,nextMonitorAt:status.nextMonitorAt,rebalanceTiming:status.rebalanceTiming,executionProgress:status.executionProgress}}
