  if(normalized.startsWith('deep oor faded'))return'執行前價格已回到深度區間外門檻內';
  if(normalized.startsWith('top-up preflight simulation failed:'))return'LP 加倉預檢模擬未通過 · '+safeEventText(text.slice(text.indexOf(':')+1),80);
  if(normalized.startsWith('cross-pool preflight simulation failed:'))return'跨池預檢模擬未通過 · '+safeEventText(text.slice(text.indexOf(':')+1),80);
  if(normalized.startsWith('gas guard:'))return'Gas 價格超出上限 · '+safeEventText(text.slice(text.indexOf(':')+1),80);
