function eventStatus(e){
  const type=String(e.type||'');
  if(type==='tx.confirmed')return{label:'鏈上交易已確認',tone:'good'};
  if(type==='tx.reverted')return{label:'鏈上交易已失敗',tone:'bad'};
  if(type==='rebalance.completed'||type==='rebalance.cross_pool_completed'||type==='bootstrap.completed')return{label:'流程完成',tone:'good'};
  if(type==='rebalance.top_up_completed')return{label:'同池加倉完成',tone:'good'};
  if(type==='tx.sent')return{label:'鏈上交易已送出',tone:'warn'};
  if(type==='rebalance.blocked')return{label:'安全條件阻擋',tone:'warn'};
  if(type==='rebalance.top_up_dry_run_blocked'||type==='rebalance.cross_pool_dry_run_blocked')return{label:'預檢阻擋',tone:'warn'};
  if(type==='rebalance.backoff')return{label:'冷卻重試',tone:'warn'};
  if(type==='rebalance.needs_attention'||type==='rebalance.recovery_required'||type==='bootstrap.recovery_required')return{label:'需人工留意',tone:'bad'};
  if(type==='lp.topup_failed')return{label:'請核對 journal',tone:'bad'};
  if(type==='rebalance.failed'||type==='cycle.failed')return{label:'執行失敗',tone:'bad'};
  if(type==='rebalance.uncommitted')return{label:'尚未完成',tone:'warn'};
  const statuses={completed:{label:'已完成',tone:'good'},blocked:{label:'已阻擋',tone:'warn'},'dry-run':{label:'預演',tone:'warn'},failed:{label:'執行失敗',tone:'bad'},recovery_required:{label:'需人工復原',tone:'bad'}};
  return statuses[String(e.status||'').toLowerCase()]||null;
}
