async function load(){const requestId=++loadSequence;try{const access=await api('/api/auth/status');if(requestId!==loadSequence)return;if(!access.tokenRequired){dashboardToken='';sessionStorage.removeItem('dashboardToken')}const fleet=await api('/api/wallets');if(requestId!==loadSequence)return;walletFleet=Array.isArray(fleet.wallets)?fleet.wallets:[];if(!walletFleet.some(item=>String(item.address).toLowerCase()===String(selectedWalletAddress).toLowerCase())){selectedWalletAddress=fleet.defaultWalletAddress||walletFleet[0]?.address||'';if(selectedWalletAddress)sessionStorage.setItem('selectedWalletAddress',selectedWalletAddress)}const requestedWallet=selectedWalletAddress;const results=await Promise.all([api('/api/state'),api('/api/control/status'),api('/api/events?limit=250'),api('/api/settings/rpc').catch(()=>null),api('/api/investment/allocation').catch(()=>null)]);if(requestId!==loadSequence||requestedWallet!==selectedWalletAddress)return;snapshot=results[0];control=results[1];rpcEndpoints=results[3]&&Array.isArray(results[3].endpoints)?results[3].endpoints:null;allocationSnapshot=results[4]||{enabled:false,allocations:[],status:'disabled'};if(allocationDraftWallet!==requestedWallet){if(allocationDraftDirty&&allocationDraftWallet)allocationDraftByWallet.set(String(allocationDraftWallet).toLowerCase(),allocationDraft.map(x=>({...x})));allocationDraftWallet=requestedWallet;const savedDraft=allocationDraftByWallet.get(String(requestedWallet).toLowerCase());allocationDraft=savedDraft?savedDraft.map(x=>({...x})):(allocationSnapshot.allocations||[]).map(x=>({...x}));allocationDraftDirty=Boolean(savedDraft)}else if(!allocationDraftDirty){allocationDraft=(allocationSnapshot.allocations||[]).map(x=>({...x}))}countdownClockOffset=Number(control.generatedAt||Date.now())-Date.now();if(typeof executionStatusWallet!=="undefined"&&executionStatusWallet===requestedWallet.toLowerCase()){const controlAt=Number(control.generatedAt||0);if(executionStatusUpdatedAt>controlAt){control=mergeExecutionFields(control,executionStatus);countdownClockOffset=executionStatusUpdatedAt-Date.now()}else{executionStatus={...(executionStatus||{}),walletAddress:requestedWallet,generatedAt:controlAt,executionPaused:control.executionPaused,cycleActive:control.cycleActive,executionBusy:control.executionBusy,recoveryRequired:control.recoveryRequired,staleExecution:control.staleExecution,nextMonitorAt:control.nextMonitorAt,rebalanceTiming:control.rebalanceTiming,executionProgress:control.executionProgress||null};executionStatusUpdatedAt=controlAt}}snapshot.events=results[2].events||[];$('authPanel').style.display='none';render()}catch(error){if(requestId!==loadSequence)return;if(error.message==='請輸入有效的中控台權杖。')$('authPanel').style.display='block';showNotice(error.message,true)}}
async function probeRpcIds(ids){if(busy||!ids.length)return;setBusy(true);let failed=0;try{for(const id of ids){try{const result=await api('/api/settings/rpc/probe',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({id})});const updated=result.result;if(updated)rpcEndpoints=(rpcEndpoints||[]).map(item=>item.id===updated.id?{...item,...updated}:item);renderRpcList()}catch(error){failed++;if(ids.length===1)showNotice(error.message,true)}}if(failed&&ids.length>1)showNotice('已完成檢測；'+failed+' 個端點未能取得檢測結果，請查看各列狀態或稍後重試。',true);else if(!failed)showNotice('RPC 檢測完成。')}finally{setBusy(false);await load()}}
async function addRpc(){if(busy)return;const input=$('rpcEndpoint'),url=input.value;if(!url){showNotice('請輸入 RPC 網址。',true);return}setBusy(true);try{const request=api('/api/settings/rpc',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:'add',url})});input.value='';await request;showNotice('RPC 已驗證並新增。')}catch(error){showNotice(error.message,true)}finally{input.value='';setBusy(false);await load()}}
async function removeRpc(id){if(busy)return;setBusy(true);try{await api('/api/settings/rpc',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:'remove',id})});showNotice('RPC 已移除。')}catch(error){showNotice(error.message,true)}finally{setBusy(false);await load()}}
document.querySelector('#rpcList').addEventListener('click',event=>{const button=event.target.closest('button[data-rpc-action]');if(!button||busy)return;const id=button.dataset.rpcId;if(button.dataset.rpcAction==='probe')probeRpcIds([id]);else if(button.dataset.rpcAction==='remove'&&confirm('確定移除此 RPC？'))removeRpc(id)});
$('probeAllRpc').onclick=()=>probeRpcIds((rpcEndpoints||[]).map(item=>item.id).filter(Boolean));
$('saveRpc').onclick=addRpc;
async function viewWallet(address){if(busy||!address||address===selectedWalletAddress)return;setBusy(true);try{await api('/api/wallet/select',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({address})});selectedWalletAddress=address;sessionStorage.setItem('selectedWalletAddress',address);draftInvestmentPoolId='';draftInvestmentMode='';if(allocationDraftDirty&&allocationDraftWallet)allocationDraftByWallet.set(String(allocationDraftWallet).toLowerCase(),allocationDraft.map(x=>({...x})));allocationDraft=[];allocationDraftDirty=false;allocationDraftWallet='';$('allocationPoolSearch').value='';$('investmentPoolSearch').value='';$('investmentPool').value='';$('rotationSource').value='';await load();showNotice('已切換檢視錢包；後續池子設定與執行控制都會套用至此錢包。')}catch(error){showNotice(error.message,true)}finally{setBusy(false)}}
document.querySelector('#walletList').addEventListener('click',event=>{const button=event.target.closest('button[data-wallet-address]');if(button&&!button.disabled)viewWallet(button.dataset.walletAddress)});
document.querySelector('#setWalletLive').onclick=async()=>{if(busy||!control)return;const enabled=control.dryRun===true;const message=enabled?'此操作會為目前檢視的錢包通過鏈上安全檢查並切換至實盤設定；自動平衡仍需另按啟動。':'此操作會將目前檢視的錢包切回預演並暫停執行。';if(!confirm('要'+(enabled?'切換為實盤':'切回預演並暫停')+'嗎？\n\n'+message))return;setBusy(true);try{await api('/api/wallet/live',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({enabled})});await load();showNotice(enabled?'實盤設定已啟用；請確認啟動條件後再啟動自動平衡。':'已切回預演並暫停。')}catch(error){showNotice(error.message,true);await load()}finally{setBusy(false)}};
async function saveInterval(field,inputId){if(busy)return;const current=control&&control.runtimeIntervals;if(!current){showNotice('尚未載入週期設定。',true);return}const seconds=Number($(inputId).value);if(!Number.isFinite(seconds)||seconds<=0){showNotice('請輸入有效的秒數。',true);return}setBusy(true);try{const result=await api('/api/settings/intervals',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({...current,[field]:Math.round(seconds*1000)})});control.runtimeIntervals=result.intervals;await load();showNotice('週期設定已儲存並立即套用。')}catch(error){showNotice(error.message,true)}finally{setBusy(false)}}
async function manualRebalance(poolId,positionId,pair){if(busy)return;const live=control&&!control.dryRun;const prompt=live?'這會嘗試送出真實鏈上交易。只有所有安全條件通過才會繼續。':'目前是預演模式，不會移動資產。';if(!confirm('要對 '+pair+' 執行人工再平衡嗎？\n\n'+prompt+'\n\n操作仍不能略過區間政策。'))return;setBusy(true);try{const result=await api('/api/control/rebalance',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({poolId,positionId,confirm:'REBALANCE'})});showNotice('操作結果：'+(result.result?.status||'已完成'));await load()}catch(error){showNotice(error.message,true);await load()}finally{setBusy(false)}}
$('positions').addEventListener('click',event=>{const button=event.target.closest('button[data-action="rebalance"]');if(button&&!button.disabled)manualRebalance(button.dataset.pool,button.dataset.pos,button.dataset.pair)});
$('markets').addEventListener('click',async event=>{const targetButton=event.target.closest('button[data-target-id]');if(targetButton&&!busy){setBusy(true);try{const result=await api('/api/pools/target',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({poolId:targetButton.dataset.targetId})});await load();showNotice(result.target.poolId?'已設定 '+result.target.pair+' 為自動平衡目標池；不會自動解除暫停。':'已清除自動平衡目標池。')}catch(error){showNotice(error.message,true)}finally{setBusy(false)}return}const button=event.target.closest('button[data-watch-id]');if(!button||busy)return;setBusy(true);try{await api('/api/pools/watch',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({poolId:button.dataset.watchId,watch:button.dataset.watchNext==='true'})});await load();showNotice('監控清單已更新。')}catch(error){showNotice(error.message,true)}finally{setBusy(false)}});
$('scan').onclick=async()=>{if(busy)return;setBusy(true);try{await api('/api/control/scan',{method:'POST'});await load();showNotice('掃描完成。')}catch(error){showNotice(error.message,true)}finally{setBusy(false)}};
$('startExecution').onclick=async()=>{if(busy||!control||!(control.startReadiness&&control.startReadiness.ready))return;const live=!control.dryRun;const message=live?'這會解除暫停並允許程式在既有安全政策通過時送出真實鏈上交易。':'目前為預演模式，只會檢查與規劃，不會移動資產。';if(!confirm('要啟動自動平衡嗎？\n\n'+message))return;setBusy(true);try{await api('/api/control/start',{method:'POST'});await load();showNotice('自動平衡已啟動。')}catch(error){showNotice(error.message,true);await load()}finally{setBusy(false)}};
$('stopLossEnabled').onchange=()=>{riskDraftDirty=true};$('stopLossPct').oninput=()=>{riskDraftDirty=true};
async function saveRisk(rebase){if(busy)return;if(rebase&&!confirm('以最新錢包與 LP 估值重新設定停損基準？這會重新計算虧損門檻。'))return;setBusy(true);try{await api('/api/risk/stop-loss',{method:'POST',body:JSON.stringify({enabled:rebase?true:$('stopLossEnabled').value==='true',lossPct:Number($('stopLossPct').value),rebase})});riskDraftDirty=false;await load();showNotice(rebase?'停損基準已重新設定；自動交易仍需按啟動。':'停損設定已儲存。')}catch(error){showNotice(error.message,true)}finally{setBusy(false)}}
$('saveStopLoss').onclick=()=>saveRisk(false);$('rebaseStopLoss').onclick=()=>saveRisk(true);
$('stopAndLiquidate').onclick=async()=>{if(busy)return;if(!confirm('停止此錢包 BOT、撤出全部 Fables LP，並將可兌換代幣換回 USDG？保留 ETH 支付 Gas；換幣成本上限 5%，未能兌換的資產將列出。'))return;setBusy(true);try{await api('/api/control/stop-liquidate',{method:'POST',body:JSON.stringify({confirm:'STOP_AND_LIQUIDATE',maxCostBps:500})});await load();showNotice('已停止新交易並排入清倉；結果與剩餘資產會持續更新。')}catch(error){showNotice(error.message,true)}finally{setBusy(false)}};
$('pauseExecution').onclick=async()=>{if(busy)return;setBusy(true);try{await api('/api/control/pause',{method:'POST'});await load();showNotice('自動平衡已暫停；錢包監控仍會繼續。')}catch(error){showNotice(error.message,true)}finally{setBusy(false)}};
